    function livingWorldState() {
        if (!planet) return null;
        const state = planet._paultendoLife ||= { discoveries: {}, decisions: [], moments: [], nextId: 1 };
        state.discoveries ||= {};
        state.decisions ||= [];
        state.moments ||= [];
        state.species ||= {};
        state.whispers ||= [];
        state.places ||= {};
        state.artifacts ||= [];
        state.artifactWork ||= [];
        state.materialWork ||= [];
        state.teachings ||= [];
        state.teachingSeen ||= {};
        state.nextId ||= 1;
        return state;
    }

