    function formatImpactEntry(entry) {
        if (!entry) return "";
        const delta = Math.round(entry.delta * 10) / 10;
        const sign = delta > 0 ? "+" : "";
        const reason = entry.reason ? entry.reason : "recent events";
        return `${entry.stat} ${sign}${delta} (${reason}, day ${entry.day})`;
    }

