    // ----------------------------------------
    // TRADE ROUTE EVENTS
    // ----------------------------------------

    // Establish new trade routes between nearby prosperous towns
    modEvent("establishTradeRoute", {
        random: true,
        auto: true,
        weight: $c.UNCOMMON,
        subject: { reg: "town", random: true },
        target: { reg: "town", nearby: true },
        value: (subject, target, args) => {
            const relations = getRelations(subject, target);
            const routeInfo = calculateRouteDifficulty(subject, target);
            args.relations = relations;
            args.routeInfo = routeInfo;
            if(!routeInfo.reachable) {args.choice='no';return true;}

            let baseYes = 0.65;
            if (routeInfo.needsShips) baseYes -= 0.15;
            if (routeInfo.difficulty > 1.5) baseYes -= 0.10;
            if (routeInfo.difficulty > 2.0) baseYes -= 0.10;

            args.choice = decideTownChoice(subject, {
                baseYes,
                minYes: 0.15,
                maxYes: 0.90,
                values: { openness: 0.10, wealth: 0.05, order: 0.02, change: 0.03 },
                influences: { trade: 0.06 },
                relations: relations,
                randomness: 0.06
            });
            return true;
        },
        check: (subject, target) => {
            if (!subject || !target) return false;
            if (subject.id === target.id) return false;

            // Need basic trade infrastructure
            if ((planet.unlocks?.trade || 0) < 20) return false;

            // Both towns need some trade influence
            if ((subject.influences?.trade || 0) < 5) return false;
            if ((target.influences?.trade || 0) < 5) return false;

            // Not at war
            if (areAtWar(subject, target)) return false;

            // Check if route already exists
            initTradeRoutes();
            const existing = planet.tradeRoutes.find(r =>
                (r.town1 === subject.id && r.town2 === target.id) ||
                (r.town1 === target.id && r.town2 === subject.id)
            );
            if (existing) return false;

            return true;
        },
        message: (subject, target, args) => {
            if (args.choice === "yes") {
                if (args.routeInfo?.needsShips) {
                    return `Ships begin sailing between {{regname:town|${subject.id}}} and {{regname:town|${target.id}}}.`;
                }
                if ((args.routeInfo?.difficulty || 1) > 1.5) {
                    return `A difficult caravan route is carved between {{regname:town|${subject.id}}} and {{regname:town|${target.id}}}.`;
                }
                return `Merchants formalize a trade route between {{regname:town|${subject.id}}} and {{regname:town|${target.id}}}.`;
            }
            return `Talks of a trade route between {{regname:town|${subject.id}}} and {{regname:town|${target.id}}} stall. Trade remains informal.`;
        },
        func: (subject, target, args) => {
            if (args.choice !== "yes") {
                if ((args.relations || 0) < 0 && Math.random() < 0.25) {
                    worsenRelations(subject, target, 1);
                }
                return;
            }

            if(!createTradeRoute(subject, target)) return;

            // Initial trade boost
            happen("Influence", null, subject, { trade: 0.5, temp: true });
            happen("Influence", null, target, { trade: 0.5, temp: true });
            improveRelations(subject, target, 1);

            // Record as a bond if history system is active
            if (typeof recordBond === "function") {
                recordBond(subject, target, "trade_partners", 10);
            }
        }
    });

    // A caravan offers actual stock to a partner with an actual use for it.
    // Arrival, payment and contact happen through the shared exchange engine.
    modEvent("caravanDeparts", {
        random:true, weight:$c.COMMON, subject:{reg:"town",random:true},
        value:subject=>{
            const routes=getTownRoutes(subject).filter(route=>{
                const partner=getRoutePartner(route,subject),path=partner&&commodityPath(subject,partner);
                return path&&Object.keys(COMMODITIES).some(type=>commodityDemand(partner,type,path)>0&&commoditySpare(subject,type,path)>0);
            });
            return routes.length?choose(routes):null;
        },
        check:(subject,_,args)=>!!args.value&&args.value.active,
        func:(subject,_,args)=>{
            const route=args.value,partner=route&&getRoutePartner(route,subject),path=partner&&commodityPath(subject,partner);
            if(!route?.active||!path)return;
            const types=Object.keys(COMMODITIES).filter(type=>commodityDemand(partner,type,path)>0&&commoditySpare(subject,type,path)>0);
            types.sort((a,b)=>commodityUnitValue(partner,b,commodityStock(partner,b),commodityDemand(partner,b,path),path)-commodityUnitValue(partner,a,commodityStock(partner,a),commodityDemand(partner,a,path),path));
            if(types.length){const record=newCommodityJourney(partner,subject,path,'caravan',types[0]);if(record)record.route=route.id;}
        }
    });

    // Trade routes can be disrupted by war
    modEvent("tradeRouteDisrupted", {
        daily: true,
        subject: { reg: "town", all: true },
        func: (subject) => {
            const routes = getTownRoutes(subject);

            routes.forEach(route => {
                const partner = getRoutePartner(route, subject);
                if (!partner) return;

                // War disrupts trade
                if (areAtWar(subject, partner)) {
                    if (route.active) {
                        route.active = false;
                        logMessage(`War disrupts the trade route between {{regname:town|${subject.id}}} and {{regname:town|${partner.id}}}.`, "warning");
                        happen("Influence", null, subject, { trade: -0.4, temp: true });
                        happen("Influence", null, partner, { trade: -0.4, temp: true });
                    }
                } else if (!route.active) {
                    // Restore after peace (with some delay)
                    if (Math.random() < 0.05) {
                        route.active = true;
                        modLog(
                            "trade",
                            `Trade resumes between {{regname:town|${subject.id}}} and {{regname:town|${partner.id}}}.`,
                            null,
                            { town: subject }
                        );
                        happen("Influence", null, subject, { trade: 0.2, temp: true });
                        happen("Influence", null, partner, { trade: 0.2, temp: true });
                    }
                }
            });
        }
    });

